import java.awt.*;import java.awt.image.*;import java.nio.file.*;import javax.swing.*;import javax.imageio.ImageIO;import java.util.*;
public class BurpHarness {
 static Path root=Path.of(System.getProperty("harness.dir"));
 static void walk(Component c,StringBuilder s){if(!c.isVisible())return;if(c instanceof AbstractButton b)s.append("BUTTON ").append(b.getText()).append(" enabled=").append(b.isEnabled()).append('\n');if(c instanceof JLabel l)s.append("LABEL ").append(l.getText()).append('\n');if(c instanceof JTextArea t)s.append("TEXT ").append(t.getText().substring(0,Math.min(t.getText().length(),4000))).append('\n');if(c instanceof Container cc)for(Component x:cc.getComponents())walk(x,s);}
 static boolean click(Component c,String text){
 if(c instanceof JTabbedPane t&&text.startsWith("TAB:")){for(int i=0;i<t.getTabCount();i++)if(t.getTitleAt(i).equals(text.substring(4))){t.setSelectedIndex(i);return true;}}if(!c.isVisible())return false;if(c instanceof AbstractButton b&&text.equals(b.getText())&&b.isEnabled()){b.doClick();return true;}if(c instanceof Container cc)for(Component x:cc.getComponents())if(click(x,text))return true;return false;}
 public static void main(String[] args)throws Exception{
  Files.createDirectories(root);new Thread(()->{int ticks=0;for(;;)try{Thread.sleep(1000);StringBuilder s=new StringBuilder();SwingUtilities.invokeAndWait(()->{for(Window w:Window.getWindows())if(w.isVisible()){s.append("WINDOW ").append(w instanceof Frame f?f.getTitle():w instanceof Dialog d?d.getTitle():w.getName()).append('\n');walk(w,s);}});Files.writeString(root.resolve("ui-state.txt"),s.toString());if(Boolean.getBoolean("harness.autoStart")){SwingUtilities.invokeAndWait(()->{for(Window w:Window.getWindows())if(w.isVisible()){click(w,"I Accept");click(w,"Next");click(w,"Start Burp");if(w instanceof Dialog d){if(d.getTitle().equals("Burp Suite is out of date"))click(w,"OK");if(d.getTitle().equals("Safe mode"))click(w,"No");if(d.getTitle().equals("Delete old temporary files?"))click(w,"Leave");}}});}
 if(++ticks%3==0){BufferedImage i=new Robot().createScreenCapture(new Rectangle(0,0,1600,1000));ImageIO.write(i,"png",root.resolve("live-screen.png").toFile());}Path command=root.resolve("command.txt");if(Files.exists(command)){String text=Files.readString(command).strip();Files.delete(command);if(text.equals("STOP"))System.exit(0);SwingUtilities.invokeAndWait(()->{boolean done=false;for(Window w:Window.getWindows())if(w.isVisible()&&click(w,text)){done=true;break;}System.out.println("HARNESS click "+text+" -> "+done);});}}catch(Throwable e){e.printStackTrace();}},"capture").start();
  Class.forName("burp.StartBurp").getMethod("main",String[].class).invoke(null,(Object)args);
 }
}
